<script>
const content={
 processor:{
  intro:"The processor is the main component that manages your computer's tasks. A faster processor helps your computer run programs smoothly and efficiently.",
  sections:[
   ["Low","Entry level processor","Good for everyday tasks","Supports music and video play"],
   ["Medium","Mid-grade processor","Multitasks well","Easily manages music and video"],
   ["High","This Product","Excels at multitasking","Power users and multimedia creation","Ideal for serious gaming"]
  ]},
 memory:{
  intro:"Random-access memory (RAM) or simply “memory,” is what allows your computer to multitask. More RAM means more applications can be running simultaneously without slowdowns.",
  sections:[
   ["Low","Great for basic tasks","Good for web browsing and streaming"],
   ["Medium","Handles heavy applications","Great for advanced gaming"],
   ["High","This Product","Manages multiple heavy apps simultaneously","Great for professional A/V editing","Ideal for serious gaming"],
   ["Graphics","The GPU (graphics processing unit), or “graphics card,” is what displays images, animations and graphics on the computer’s screen. A more powerful GPU makes games run faster and look better.","Entry-Level","Budget friendly","Basic gaming","Mid-Range","Most common GPU","Fast display","High performance gaming"]
  ]},
 graphics:{
  intro:"The GPU (graphics processing unit), or “graphics card,” is what displays images, animations and graphics on the computer’s screen. A more powerful GPU makes games run faster and look better.",
  sections:[
   ["Entry-Level","Budget friendly","Basic gaming"],
   ["Mid-Range","Most common GPU","Fast display","High performance gaming"],
   ["High-End","This Product","Offers gameplay at max settings","Powerful and efficient","Ideal for gaming enthusiasts"]
  ]},
 storage:{
  intro:"Storage type is one of the most important factors to consider as you decide which new computer to purchase. The right storage type for you will depend on your budget, the amount of storage space you’ll need and the types of programs you’ll use.",
  sections:[
   ["HDD","Large file and content capacity","Costs less per gigabyte than SSD","Great for everyday use"],
   ["SSD","This Product","Some capacity for HD files","Apps and games run faster than with HDD","Optimal gaming performance"],
   ["HDD+SSD","SSD speed + HDD capacity","Fast startup; generous storage","Optimal gaming performance"]
  ]},
 capacity:{
  intro:"Storage capacity determines how much data you can store on your computer. If you typically store small files (word documents and spreadsheets) and run basic programs, you can get by with a lower storage capacity. You’ll want to consider higher storage capacity if you do a lot of photo or video editing, or if you use your computer for large gaming installs.",
  sections:[
   ["Small","Great for working with small files","Runs basic programs","Add cloud storage for extra space"],
   ["Medium","Great for most uses","Starting point for gaming or high-res video","Some photo/video editing"],
   ["Large","This Product","High resolution video","Higher cost gives more storage","Great for large game installs"]
  ]}
};
function render(tab){
 const d=content[tab]; let html=`<p>${d.intro}</p>`;
 d.sections.forEach((s,i)=>{
   if(s[0]==="Graphics"){html+=`<h3>${s[1]}</h3>`; html+=`<div class="level"><div class="levelTitle">▧ &nbsp;Entry-Level</div><ul><li>Budget friendly</li><li>Basic gaming</li></ul></div><div class="level"><div class="levelTitle">▧ &nbsp;Mid-Range</div><ul><li>Most common GPU</li><li>Fast display</li><li>High performance gaming</li></ul></div>`;return}
   const isThis=s.includes("This Product");
   html+=`<div class="level ${isThis?'this':''}"><div class="levelTitle">▣ &nbsp;${s[0]} ${isThis?'<span>This Product</span>':''}</div><ul>${s.slice(1).filter(x=>x!=="This Product").map(x=>`<li>${x}</li>`).join('')}</ul></div>`;
 });
 document.getElementById('drawerContent').innerHTML=html;
 document.querySelectorAll('.tab').forEach(x=>x.classList.toggle('active',x.dataset.tab===tab));
}
function openDrawer(tab){document.getElementById('overlay').style.display='block';render(tab)}
document.querySelectorAll('[data-tab]').forEach(el=>el.addEventListener('click',()=>openDrawer(el.dataset.tab)));
document.getElementById('close').onclick=()=>document.getElementById('overlay').style.display='none';
document.getElementById('overlay').addEventListener('click',e=>{if(e.target.id==='overlay')e.currentTarget.style.display='none'});
</script>
